import{_ as o,a0 as l,w as n,s as r,I as i,x as s,a1 as t,A as d,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"FreeDOS 操作目錄和文件的基本命令 | LCTT x X-CMD","titleTemplate":false,"description":"FreeDOS 操作目錄和文件的基本命令 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"FreeDOS 操作目錄和文件的基本命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"FreeDOS 操作目錄和文件的基本命令 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210403 FreeDOS commands you need to know","title":"FreeDOS 操作目錄和文件的基本命令","tag":"202112","desc":""},"relativePath":"202112/20210403 FreeDOS commands you need to know.md","filePath":"[post].md"}'),c={name:"202112/20210403 FreeDOS commands you need to know.md"};function h(g,e,k,u,b,C){const a=l("Link");return n(),r("div",null,[e[18]||(e[18]=i("h1",{id:"freedos-操作目錄和文件的基本命令",tabindex:"-1"},[s("FreeDOS 操作目錄和文件的基本命令 "),i("a",{class:"header-anchor",href:"#freedos-操作目錄和文件的基本命令","aria-label":"Permalink to “FreeDOS 操作目錄和文件的基本命令”"},"​")],-1)),e[19]||(e[19]=i("blockquote",null,[i("p",null,"學習如何在 FreeDOS 中對目錄和文件執行創建、移除、複製等任務。")],-1)),e[20]||(e[20]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202112/12/100340gffegjttbn0n7iox.jpg",alt:""})],-1)),i("p",null,[e[1]||(e[1]=s("DOS 的開源實現 ",-1)),t(a,{href:"https://www.freedos.org/"},{default:d(()=>[...e[0]||(e[0]=[s("FreeDOS",-1)])]),_:1}),e[2]||(e[2]=s(" 提供了一個輕量級的操作系統，可以在現代硬件（或模擬器）上用於運行歷史遺留下來的應用程序，可以更新硬件供應商不兼容於 Linux 的固件閃存。熟悉 FreeDOS 不僅是一種對舊計算機時代的有趣考古，也是一種獲取有用的計算機技能的投入。在這篇文章中，我將介紹一些在 FreeDOS 系統上工作所需要知道的基本命令。",-1))]),e[21]||(e[21]=p(`<h3 id="基本的命令和文件命令" tabindex="-1">基本的命令和文件命令 <a class="header-anchor" href="#基本的命令和文件命令" aria-label="Permalink to “基本的命令和文件命令”">​</a></h3><p>FreeDOS 在硬盤驅動器上使用目錄來組織文件。這意味着你需要使用目錄命令來創建一個結構，用於存儲和查找你在其中存儲的文件。你所需要的用於管理目錄結構的命令有：</p><ul><li><code>MD</code> （或 <code>MKDIR</code>） 創建一個新的目錄或子目錄。</li><li><code>RD</code> （或 <code>RMDIR</code>） 移除（刪除） 一個目錄或子目錄。</li><li><code>CD</code> （或 <code>CHDIR</code>） 從當前工作目錄更改到另一個命令。</li><li><code>DELTREE</code> 刪除一個目錄，包括其包含的任意文件或子目錄。</li><li><code>DIR</code> 列出當前工作目錄的內容。</li></ul><p>因為使用目錄是 FreeDOS 的主要工作，所有的這些命令（除 DELTREE 以外）是包含在 <code>COMMAND.COM</code> 中的內部命令。因此，它們將被加載到內存之中，並在你啓動（即使是從啓動盤啓動）時隨時可用。前三個命令有兩個版本：一個版本是兩個字母的短名，一個版本是長名。在實踐中沒有區別，因此，我將在這篇文章中使用短名。</p><h3 id="使用-md-創建一個目錄" tabindex="-1">使用 MD 創建一個目錄 <a class="header-anchor" href="#使用-md-創建一個目錄" aria-label="Permalink to “使用 MD 創建一個目錄”">​</a></h3><p>FreeDOS 的 <code>MD</code> 命令會創建一個新的目錄或子目錄。（實際上，由於 <code>\\</code> 是根目錄，從技術上講，所有的目錄都是子目錄，因此，我更喜歡在所有的示例中使用“子目錄”的説法）。有一個可選的參數是你所想要創建目錄的路徑，但是如果不包含路徑，將在當前工作子目錄中創建子目錄。</p><p>例如，為在你的當前位置創建一個名稱為 <code>letters</code> 的子目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\HOME\\&gt;MD LETTERS</span></span></code></pre></div><p>這會創建子目錄 <code>C:\\letters</code> 。</p><p>通過包含一個路徑，你可以在任意位置創建一個子目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;MD C:\\HOME\\LETTERS\\LOVE</span></span></code></pre></div><p>這和先移動到 <code>C:\\HOME\\LETTERS</code> ，然後在其中創建一個子目錄的結果相同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\CD HOME\\LETTERS</span></span>
<span class="line"><span>C:\\HOME\\LETTERS\\&gt;MD LOVE</span></span>
<span class="line"><span>C:\\HOME\\LETTERS\\&gt;DIR</span></span>
<span class="line"><span>LOVE</span></span></code></pre></div><p>一個路徑描述不能超過 63 個字符，包括反斜槓在內。</p><h3 id="使用-rd-移除一個目錄" tabindex="-1">使用 RD 移除一個目錄 <a class="header-anchor" href="#使用-rd-移除一個目錄" aria-label="Permalink to “使用 RD 移除一個目錄”">​</a></h3><p>FreeDOS 的 <code>RD</code> 命令會移除一個子目錄。這個子目錄必須是空的。如果它包含文件或其它是子目錄，你將會得到錯誤信息。它也有一個可選的路徑參數，語法與 <code>MD</code> 的相同。</p><p>你不能移除你的當前工作子目錄。為移除此目錄，你必須 <code>CD</code> 到其父目錄，然後再移除不需要的子目錄。</p><h3 id="使用-deltree-刪除文件和目錄" tabindex="-1">使用 DELTREE 刪除文件和目錄 <a class="header-anchor" href="#使用-deltree-刪除文件和目錄" aria-label="Permalink to “使用 DELTREE 刪除文件和目錄”">​</a></h3><p><code>RD</code> 命令可能會讓人有點迷糊，因為在該命令中內置了保護 FreeDOS 的措施。例如，你不能刪除一個包含內容的子目錄是一種安全措施。<code>DELTREE</code> 就是解決方案。</p><p><code>DELTREE</code> 命令會刪除整個子目錄“樹”（子目錄）、其包含的所有的文件，以及其包含的所有的子目錄及其包含的所有的文件等等，上述的一切都在一個簡單的命令中完成。有時，它可能有點 <em>太</em> 容易了，因為它可以如此快速地擦除數據。它是忽略文件屬性的，因此你可以擦除隱藏、只讀，和未知的系統文件。</p><p>你甚至可以在命令中具體指定多個目錄樹來擦除它們。這條命令將在一個命令中擦除這兩個目錄中的所有子目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;DELTREE C:\\FOO C:\\BAR</span></span></code></pre></div><p>這是那些使用前需要三思的命令中的其中一個。毫無疑問，它自然有其價值。我仍然對轉到每個子目錄，刪除個別文件，檢查每個子目錄的內容，一次刪除一個子目錄, 然後再跳轉到上一層目錄，重複上述過程的乏味而記憶猶新。<code>DELTREE</code> 在你需要時是非常省時。但是我從不會將其用於日常維護，因為一此失誤都能造成重大的損失。</p><h3 id="格式化一個硬盤驅動器" tabindex="-1">格式化一個硬盤驅動器 <a class="header-anchor" href="#格式化一個硬盤驅動器" aria-label="Permalink to “格式化一個硬盤驅動器”">​</a></h3><p><code>FORMAT</code> 命令也可以用於準備一個空白的硬盤驅動器來將文件寫入其中。這將格式化 <code>D:</code> 驅動器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;FORMAT D:</span></span></code></pre></div><h3 id="複製文件" tabindex="-1">複製文件 <a class="header-anchor" href="#複製文件" aria-label="Permalink to “複製文件”">​</a></h3><p><code>COPY</code> 命令，顧名思義，將文件從一個位置複製到另一個位置。所需要的參數是：將要被複制的文件、要將其複製到的路徑和文件。開關選項包含：</p><ul><li><code>/Y</code> 當一個文件要被覆蓋時，避免出現提示。</li><li><code>/-Y</code> 當一個文件要被覆蓋時，需要出現提示。</li><li><code>/V</code> 驗證副本的內容。</li></ul><p>這將從 <code>C:</code> 上的工作目錄中複製文件 <code>MYFILE.TXT</code> 到 <code>D:</code> 驅動器的根目錄，並將其重命名為 <code>EXAMPLE.TXT</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;COPY MYFILE.TXT D:\\EXAMPLE.TXT</span></span></code></pre></div><p>這將從 <code>C:</code> 上的工作目錄中複製文件 <code>EXAMPLE.TXT</code> 到 <code>C:\\DOCS\\</code> 目錄，接下來驗證文件的內容來確保副本是完整的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;COPY EXAMPLE.TXT C:\\DOCS\\EXAMPLE.TXT /V</span></span></code></pre></div><p>你也可以使用 <code>COPY</code> 命名來合併和追加文件。這個命令將合併兩個文件 <code>MYFILE1.TXT</code> 和 <code>MYFILE2.TXT</code> ，並將其放置到一個新的名稱為 <code>MYFILE3.TXT</code> 的文件之中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;COPY MYFILE1.TXT+MYFILE2.TXT MYFILE3.TXT</span></span></code></pre></div><h3 id="使用-xcopy-複製目錄" tabindex="-1">使用 XCOPY 複製目錄 <a class="header-anchor" href="#使用-xcopy-複製目錄" aria-label="Permalink to “使用 XCOPY 複製目錄”">​</a></h3><p><code>XCOPY</code> 命令將複製整個目錄以及它們的所有的子目錄和這些子目錄中包含的所有的文件。參數是將要複製的文件和其路徑，以及將要複製到的目的地。重要的開關選項是：</p><ul><li><code>/S</code> 複製當前目錄及其子目錄中的所有文件。</li><li><code>/E</code> 複製子目錄，即使它們是空的。這個選項必須和 <code>/S</code> 一起使用。</li><li><code>/V</code> 驗證其所製作的副本。</li></ul><p>這是一個非常強大和有用的命令，尤其是用於備份目錄或整個硬盤驅動器。</p><p>這個命令將複製目錄 <code>C:\\DOCS</code> 的全部內容，包括所有的子目錄及其內容（除了空的子目錄以外），並將其放置到驅動器 <code>D:</code> 的目錄 <code>D:\\BACKUP\\DOCS\\</code> 之中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;XCOPY C:\\DOCS D:\\BACKUP\\DOCS\\ /S</span></span></code></pre></div><h3 id="使用-freedos" tabindex="-1">使用 FreeDOS <a class="header-anchor" href="#使用-freedos" aria-label="Permalink to “使用 FreeDOS”">​</a></h3><p>FreeDOS 是一個有趣的、輕量的、開源的操作系統。不管你正在使用它來更新你的主板的固件，還是給予舊計算機新生，它都能提供很多有用的實用程序，可以使你能夠很好地使用它工作。學習 FreeDOS 的基本知識。你都可能會被它的多才多藝所驚訝。</p><hr>`,44)),i("p",null,[e[4]||(e[4]=s("via: ",-1)),t(a,{href:"https://opensource.com/article/21/4/freedos-commands"},{default:d(()=>[...e[3]||(e[3]=[s("https://opensource.com/article/21/4/freedos-commands",-1)])]),_:1})]),i("p",null,[e[9]||(e[9]=s("作者：",-1)),t(a,{href:"https://opensource.com/users/ahuka"},{default:d(()=>[...e[5]||(e[5]=[s("Kevin O'Brien",-1)])]),_:1}),e[10]||(e[10]=s(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:d(()=>[...e[6]||(e[6]=[s("lujun9972",-1)])]),_:1}),e[11]||(e[11]=s(" 譯者：",-1)),t(a,{href:"https://github.com/robsean"},{default:d(()=>[...e[7]||(e[7]=[s("robsean",-1)])]),_:1}),e[12]||(e[12]=s(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:d(()=>[...e[8]||(e[8]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[15]||(e[15]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[13]||(e[13]=[s("LCTT",-1)])]),_:1}),e[16]||(e[16]=s(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:d(()=>[...e[14]||(e[14]=[s("Linux中國",-1)])]),_:1}),e[17]||(e[17]=s(" 榮譽推出",-1))])])}const E=o(c,[["render",h]]);export{f as __pageData,E as default};
